<script setup lang="ts">
import type {ApiClient,PublicProduct} from '@kuaixie/sdk';
import {t,formatAmount,formatDate} from '@kuaixie/i18n';
import AddressSelection from './AddressSelection.vue';
import InsuranceSelection from './InsuranceSelection.vue';
import {useProductCheckout} from './useProductCheckout';
const props=defineProps<{client:ApiClient;product:PublicProduct}>();
const p=useProductCheckout(props.client,()=>props.product,async(title,body)=>window.confirm(title+'\n'+body));
</script>
<template><section class="product-checkout"><h2>{{t('checkout.title')}}</h2><p>{{t('checkout.boundary')}}</p><p v-if="p.error.value" role="alert">{{p.error.value}}</p><template v-if="p.created.value"><p role="status">{{t('checkout.created')}}</p><a :href="'#services/my-orders'">{{t('account.myOrders')}}</a><p>{{p.created.value.id}}</p></template><template v-else><fieldset :disabled="p.busy.value||!!p.pending.value"><legend>{{t('checkout.delivery')}}</legend><label>{{t('checkout.trip')}}<select v-model="p.form.tripId" required><option value="">{{t('checkout.chooseTrip')}}</option><option v-for="trip in p.trips.value" :key="trip.id" :value="trip.id">{{trip.destination}} · {{formatDate(trip.depart_date)}} · {{trip.remaining_slots}}</option></select></label><p v-if="!p.loading.value&&!p.trips.value.length">{{t('checkout.noTrips')}}</p><button type="button" :disabled="p.loading.value" @click="p.loadTrips()">{{t('common.retry')}}</button><button v-if="p.more.value" type="button" :disabled="p.loading.value" @click="p.loadTrips(true)">{{t('account.more')}}</button><label>{{t('checkout.quantity')}}<input v-model="p.form.quantity" type="number" min="1" max="100" step="1" inputmode="numeric"/></label><AddressSelection :client="client" @selected="p.setAddress"/><label>{{t('checkout.contactName')}}<input v-model="p.form.contactName" maxlength="64" autocomplete="name"/></label><label>{{t('checkout.contactPhone')}}<input v-model="p.form.contactPhone" maxlength="24" autocomplete="tel"/></label><label>{{t('checkout.address')}}<textarea v-model="p.form.address" maxlength="512" autocomplete="street-address"/></label><label>{{t('checkout.expectDate')}}<input v-model="p.form.expectDate" type="date"/></label><label>{{t('checkout.note')}}<textarea v-model="p.form.note" maxlength="1024"/></label><label>{{t('checkout.insuranceChoice')}}<select v-model="p.form.insuranceChoice"><option value="waived">{{t('checkout.waiveInsurance')}}</option><option value="yes">{{t('checkout.chooseInsurance')}}</option></select></label><InsuranceSelection v-if="p.form.insuranceChoice==='yes'&&p.form.tripId&&!p.pending.value" :client="client" subject-type="trip" :subject-id="p.form.tripId" :item-name="product.name" :declared-value="p.declaredValue.value" @selected="p.setInsurance"/><button type="button" :disabled="!p.form.tripId" @click="p.prepare()">{{t('checkout.quote')}}</button></fieldset><article v-if="p.quote.value" aria-live="polite"><h3>{{t('checkout.quote')}}</h3><dl><dt>{{t('checkout.unitPrice')}}</dt><dd>{{formatAmount(p.quote.value.unitPrice,'CNY')}}</dd><dt>{{t('checkout.goods')}}</dt><dd>{{formatAmount(p.quote.value.goodsAmount,'CNY')}}</dd><dt>{{t('checkout.serviceFee')}}</dt><dd>{{formatAmount(p.quote.value.serviceFee,'CNY')}}</dd><dt>{{t('checkout.escrow')}}</dt><dd>{{formatAmount(p.quote.value.buyerEscrow,'CNY')}}</dd></dl><p>{{t('checkout.insuranceDirect')}}</p><p>{{t('checkout.intentWindow',{hours:p.quote.value.intentHours})}}</p><button :disabled="p.busy.value||!!p.pending.value" @click="p.submit()">{{t('checkout.confirmTitle')}}</button></article><p v-if="p.pending.value">{{t('checkout.unconfirmed')}}</p><button v-if="p.pending.value" :disabled="p.busy.value" @click="p.submit()">{{t('case.retryPending')}}</button><a href="#services/buyer-verify">{{t('checkout.verifyBuyer')}}</a></template></section></template>
<style scoped>.product-checkout{border-top:1px solid #cbd5e1;padding-top:22px;margin-top:22px}.product-checkout fieldset{display:grid;gap:12px}.product-checkout label{display:grid;gap:6px}.product-checkout input,.product-checkout select,.product-checkout textarea{padding:10px;max-width:100%}.product-checkout button{padding:10px;cursor:pointer}.product-checkout [role=alert]{color:#b42318}.product-checkout dd{margin:4px 0 12px}.product-checkout p{line-height:1.7}</style>
